import SwiftUI
import SwiftData

struct SavingsGoalsView: View { @Query private var goals: [SavingsGoal]; @State private var adding = false; var body: some View { List { if goals.isEmpty { ContentUnavailableView("创建一个储蓄目标", systemImage: "target", description: Text("把计划变成看得见的进度")); Button("创建目标") { adding = true }.frame(maxWidth: .infinity) } else { ForEach(goals) { NavigationLink { SavingsGoalDetailView(goal: $0) } label: { SavingsGoalCard(goal: $0) }.listRowInsets(.init()).listRowBackground(Color.clear) } } }.navigationTitle("储蓄目标").toolbar { Button("新增目标", systemImage: "plus") { adding = true } }.sheet(isPresented: $adding) { SavingsGoalEditorView() } } }
struct SavingsGoalCard: View { let goal: SavingsGoal; private var progress: Double { goal.targetAmount > 0 ? goal.currentAmount.doubleValue / goal.targetAmount.doubleValue : 0 }; var body: some View { VStack(alignment: .leading, spacing: 12) { HStack { Text(goal.emoji).font(.largeTitle); VStack(alignment: .leading) { Text(goal.name).font(.headline); Text(goal.type.title).font(.caption).foregroundStyle(.secondary) }; Spacer(); Text(progress.formatted(.percent.precision(.fractionLength(1)))).font(.headline) }; ProgressView(value: min(progress, 1)).tint(Color(hex: goal.colorHex)); HStack { metric("目标", goal.targetAmount); Spacer(); metric("已存", goal.currentAmount); Spacer(); metric("剩余", max(0, goal.targetAmount - goal.currentAmount)) } }.padding(18).background(Color(hex: goal.colorHex).opacity(0.10), in: RoundedRectangle(cornerRadius: 20)) }; private func metric(_ title: String, _ value: Decimal) -> some View { VStack(alignment: .leading) { Text(title).font(.caption).foregroundStyle(.secondary); AmountText(amount: value, font: .subheadline.bold()) } } }
struct SavingsGoalDetailView: View { @Environment(\.modelContext) private var context; @Environment(\.dismiss) private var dismiss; let goal: SavingsGoal; @State private var editing = false; @State private var operation: SavingsOperation?; @State private var deleting = false; var body: some View { List { Section { SavingsGoalCard(goal: goal).listRowInsets(.init()).listRowBackground(Color.clear) }; Section { HStack { Button("存一笔", systemImage: "plus.circle") { operation = .deposit }.buttonStyle(.borderedProminent); Spacer(); Button("取出", systemImage: "minus.circle") { operation = .withdraw }.buttonStyle(.bordered) } }; Section("计划") { LabeledContent("开始日期", value: goal.startDate.formatted(DateFormats.shortDay)); LabeledContent("目标日期", value: goal.targetDate?.formatted(DateFormats.shortDay) ?? "无结束日期"); if goal.type == .periodic { LabeledContent("定期计划", value: "\(goal.frequency.title) " + CurrencyFormatter.string(goal.periodicAmount)) } }; Section("历史记录") { if goal.records.isEmpty { ContentUnavailableView("暂无存款记录", systemImage: "clock") } else { ForEach(goal.records.sorted { $0.date > $1.date }) { record in HStack { VStack(alignment: .leading) { Text(record.amount >= 0 ? "存入" : "取出"); Text(record.date, format: DateFormats.full).font(.caption).foregroundStyle(.secondary) }; Spacer(); AmountText(amount: abs(record.amount), type: record.amount >= 0 ? .income : .expense) } } } }; Section { Button("删除目标", systemImage: "trash", role: .destructive) { deleting = true }.frame(maxWidth: .infinity) } }.navigationTitle(goal.name).toolbar { Button("编辑") { editing = true } }.sheet(isPresented: $editing) { SavingsGoalEditorView(goal: goal) }.sheet(item: $operation) { SavingsOperationView(goal: goal, operation: $0) }.confirmationDialog("删除储蓄目标？", isPresented: $deleting) { Button("删除", role: .destructive) { context.delete(goal); try? context.save(); dismiss() } } } }
enum SavingsOperation: String, Identifiable { case deposit, withdraw; var id: Self { self }; var title: String { self == .deposit ? "存一笔" : "取出" } }
struct SavingsOperationView: View { @Environment(\.dismiss) private var dismiss; @Environment(\.modelContext) private var context; let goal: SavingsGoal; let operation: SavingsOperation; @State private var amount = ""; @State private var note = ""; @State private var errorMessage: String?; var body: some View { NavigationStack { Form { TextField("金额", text: $amount).keyboardType(.decimalPad); TextField("备注", text: $note) }.navigationTitle(operation.title).toolbar { ToolbarItem(placement: .cancellationAction) { Button("取消") { dismiss() } }; ToolbarItem(placement: .confirmationAction) { Button("保存") { save() } } }.alert("无法保存", isPresented: .constant(errorMessage != nil)) { Button("好") { errorMessage = nil } } message: { Text(errorMessage ?? "") } } }; private func save() { guard let value = Decimal(string: amount), value > 0 else { errorMessage = "金额必须大于 0"; return }; if operation == .withdraw && value > goal.currentAmount { errorMessage = "取出金额不能超过已存金额"; return }; let signed = operation == .deposit ? value : -value; goal.currentAmount += signed; context.insert(SavingsRecord(amount: signed, note: note, goal: goal)); do { try context.save(); dismiss() } catch { goal.currentAmount -= signed; errorMessage = error.localizedDescription } } }
struct SavingsGoalEditorView: View { @Environment(\.dismiss) private var dismiss; @Environment(\.modelContext) private var context; var goal: SavingsGoal?; @State private var name: String; @State private var emoji: String; @State private var target: String; @State private var type: SavingsGoalType; @State private var start: Date; @State private var hasTargetDate: Bool; @State private var targetDate: Date; @State private var frequency: Frequency; @State private var periodic: String; @State private var color = "#AF52DE"; @State private var errorMessage: String?; init(goal: SavingsGoal? = nil) { self.goal = goal; _name = State(initialValue: goal?.name ?? ""); _emoji = State(initialValue: goal?.emoji ?? "🎯"); _target = State(initialValue: goal.map { "\($0.targetAmount)" } ?? ""); _type = State(initialValue: goal?.type ?? .flexible); _start = State(initialValue: goal?.startDate ?? .now); _hasTargetDate = State(initialValue: goal?.targetDate != nil); _targetDate = State(initialValue: goal?.targetDate ?? Calendar.current.date(byAdding: .month, value: 6, to: .now) ?? .now); _frequency = State(initialValue: goal?.frequency ?? .monthly); _periodic = State(initialValue: goal.map { "\($0.periodicAmount)" } ?? "") }; var body: some View { NavigationStack { Form { TextField("目标名称", text: $name); TextField("Emoji", text: $emoji); TextField("目标金额", text: $target).keyboardType(.decimalPad); Picker("储蓄方式", selection: $type) { ForEach(SavingsGoalType.allCases) { Text($0.title).tag($0) } }; if type == .periodic { Picker("频率", selection: $frequency) { ForEach(Frequency.allCases) { Text($0.title).tag($0) } }; TextField("每期金额", text: $periodic).keyboardType(.decimalPad) }; DatePicker("开始日期", selection: $start, displayedComponents: .date); Toggle("设置目标日期", isOn: $hasTargetDate); if hasTargetDate { DatePicker("目标日期", selection: $targetDate, in: start..., displayedComponents: .date) }; ColorPicker("目标颜色", selection: Binding(get: { Color(hex: color) }, set: { _ in })) }.navigationTitle(goal == nil ? "新增储蓄目标" : "编辑储蓄目标").toolbar { ToolbarItem(placement: .cancellationAction) { Button("取消") { dismiss() } }; ToolbarItem(placement: .confirmationAction) { Button("保存") { save() } } }.alert("无法保存", isPresented: .constant(errorMessage != nil)) { Button("好") { errorMessage = nil } } message: { Text(errorMessage ?? "") } } }; private func save() { guard let value = Decimal(string: target), value > 0, !name.isEmpty else { errorMessage = "请填写有效名称和目标金额"; return }; if hasTargetDate && targetDate < start { errorMessage = "目标日期不能早于开始日期"; return }; let per = Decimal(string: periodic) ?? 0; let model = goal ?? SavingsGoal(name: name, emoji: emoji, targetAmount: value); model.name = name; model.emoji = emoji; model.targetAmount = value; model.typeRaw = type.rawValue; model.startDate = start; model.targetDate = hasTargetDate ? targetDate : nil; model.frequencyRaw = frequency.rawValue; model.periodicAmount = per; if goal == nil { context.insert(model) }; do { try context.save(); dismiss() } catch { errorMessage = error.localizedDescription } } }
